; ---------------------------------------------------------------

.segment	"CODE"

.proc	_game_hasee_bounce: near

.segment	"CODE"

;
; HASEE_RESET_PLAYER_FLAGS_START_FRAME();
;
	lda     _player_flags2
	and     #$FE
	sta     _player_flags2
;
; pad1 = pad_poll(0); // read the first controller
;
	lda     #$00
	jsr     _pad_poll
	sta     _pad1
;
; pad1_new = get_pad_new(0);
;
	lda     #$00
	jsr     _get_pad_new
	sta     _pad1_new
;
; pad2 = pad_poll(1); // Will only be used in 2 Player games
;
	lda     #$01
	jsr     _pad_poll
	sta     _pad2
;
; pad2_new = get_pad_new(1); // Or maybe we just call a second function that lets the grounded hasee move only in 2p
;
	lda     #$01
	jsr     _get_pad_new
	sta     _pad2_new
;
; ppu_wait_nmi(); // wait till beginning of the frame
;
	jsr     _ppu_wait_nmi
;
; clear_vram_buffer();
;
	jsr     _clear_vram_buffer
;
; hasee_singleplayer_movement();
;
	jsr     _hasee_singleplayer_movement
;
; hasee_treat_movement();
;
	jsr     _hasee_treat_movement
;
; hasee_sprite_collisions();
;
	jsr     _hasee_sprite_collisions
;
; hasee_draw_sprites();
;
	jsr     _hasee_draw_sprites
;
; handle_tile_clear_queue();
;
	jsr     _handle_tile_clear_queue
;
; if (HASEE_SCORE_CHANGED_THIS_FRAME) { hasee_update_score(); }
;
	lda     _player_flags2
	and     #$01
	beq     L05D8
	jsr     _hasee_update_score
;
; --level_timer;
;
L05D8:	lda     _temp6
	sec
	sbc     #$01
	sta     _temp6
	bcs     L05DD
	dec     _temp6+1
;
; if (level_timer == 0) {
;
L05DD:	lda     _temp6
	ora     _temp6+1
	bne     L05DE
;
; level_timer = LEVEL_FRAME_LENGTH;
;
	ldx     #$07
	lda     #$08
	sta     _temp6
	stx     _temp6+1
;
; ++level;
;
	inc     _level_index
;
; --game_timer;
;
L05DE:	lda     _pseudo_scroll_y
	sec
	sbc     #$01
	sta     _pseudo_scroll_y
	bcs     L05E5
	dec     _pseudo_scroll_y+1
;
; if (game_timer == 0) {
;
L05E5:	lda     _pseudo_scroll_y
	ldx     _pseudo_scroll_y+1
	cpx     #$00
	bne     L05E8
	cmp     #$00
L05E8:	jsr     booleq
;
; --treat_timer;
;
	dec     _did_headbonk
;
; if (treat_timer == 0) {
;
	jne     L05F2
;
; treat_timer = 32 + (rand8() & 0b11111);
;
	jsr     _rand8
	and     #$1F
	clc
	adc     #$20
	sta     _did_headbonk
;
; calculate_next_treat();
;
	jsr     _calculate_next_treat
;
; for (x = 0; x < MAX_TREATS_ONSCREEN; ++x) {
;
	lda     #$00
	sta     _x
L093A:	lda     _x
	cmp     #$0C
	jcs     L05F2
;
; if (!IS_ENEMY_ACTIVE(x)) {
;
	ldy     _x
	lda     _enemies_flags,y
	and     #$80
	jne     L093D
;
; temp0 = rand8();
;
	jsr     _rand8
	sta     _temp0
;
; enemies_type[x] = temp4;
;
	ldy     _x
	lda     _temp4
	sta     _enemies_type,y
;
; level_index = temp4;
;
	lda     _temp4
	sta     _level_index
;
; enemies_flags[x] = temp0 & 0b1; // set initial direction based on RNG
;
	lda     #<(_enemies_flags)
	ldx     #>(_enemies_flags)
	clc
	adc     _x
	bcc     L0608
	inx
L0608:	sta     ptr1
	stx     ptr1+1
	lda     _temp0
	and     #$01
	ldy     #$00
	sta     (ptr1),y
;
; ACTIVATE_ENEMY(x);
;
	ldy     _x
	lda     _enemies_flags,y
	ora     #$80
	sta     _enemies_flags,y
;
; enemies_y[x] = divide_by_3(temp0) + 80;
;
	lda     #<(_enemies_y)
	ldx     #>(_enemies_y)
	clc
	adc     _x
	bcc     L0614
	inx
L0614:	jsr     pushax
	lda     _temp0
	jsr     _divide_by_3
	clc
	adc     #$50
	ldy     #$00
	jsr     staspidx
;
